"""Check that the block literals of a certificate generated by gen12.py spell a given word file.

    verify_blocks12.py NAME WORD.txt [DIR]

Reads DIR/Superperm/NAME/B*.lean, Tree.lean and Main.lean (DIR: by default the directory of this script;
nothing of gen12.py is used): the blocks `b0, b1, …`, the block length B, the number of shared letters and
the depth from the `okT` line of Tree.lean, the word length from `hasWord`.  Block i, read backwards, must be
the letters B*i .. B*i+B+Kw-1 of the word (as far as the word goes; '0' beyond it), with the letters of the
file ranked in ASCII order; the leaves of the tree must be b0, b1, … in this order.  One block file is held in
memory at a time.  Prints the SHA-256 of the file.

A file whose name ends in .xz is decompressed.  Python 3, no packages.
"""
import sys, os, re, glob, hashlib
name, wordfile = sys.argv[1], sys.argv[2]
here = sys.argv[3] if len(sys.argv) > 3 else os.path.dirname(os.path.abspath(__file__))
d = os.path.join(here, 'Superperm', name)
tree = open(os.path.join(d, 'Tree.lean'), encoding='utf-8').read()
B, Kw, mW, depth = map(int, re.search(r'theorem tree_ok : okT (\d+) (\d+) (\d+) (\d+) tree = true', tree).groups())
assert re.search(r'def W : Nat := valT %d %d tree\n' % (B, depth), tree)
main = open(os.path.join(d, 'Main.lean'), encoding='utf-8').read()
K, L = map(int, re.search(r'theorem hasWord : HasWord (\d+) (\d+)', main).groups())
assert Kw == 2 * K - 1 and mW == 16 ** Kw - 1
if wordfile.endswith('.xz'):
    import lzma
    data = lzma.open(wordfile).read()
else:
    data = open(wordfile, 'rb').read()
raw = data.rstrip(b'\r\n')
sha = hashlib.sha256(data).hexdigest()
syms = sorted(set(raw[:1 << 20]) | set(raw[-(1 << 20):]))
assert len(syms) == K and len(raw) == L, (len(syms), len(raw))
word = raw.translate(bytes.maketrans(bytes(syms), b'0123456789abcdef'[:K]))
assert not set(word[::997]) - set(b'0123456789abcdef'[:K])
del data, raw
nxt = 0; files = sorted(glob.glob(os.path.join(d, 'B*.lean')))
for fi, fn in enumerate(files):
    s = open(fn, encoding='utf-8').read()
    ids = []
    for m in re.finditer(r'^def b(\d+) : Nat := 0x([0-9a-f]+)$', s, re.M):
        i = int(m.group(1)); ids.append(i)
        assert i == nxt, 'block %d out of order' % i
        want = word[B * i:B * i + B + Kw][::-1].decode() or '0'
        assert m.group(2) == want, 'block %d differs' % i
        nxt += 1
    # the subtree of this file has these blocks as its leaves, in order
    sub = s[s.index('def s%d : WT' % fi):s.index('theorem s%d_ok' % fi)]
    assert [int(x) for x in re.findall(r'WT\.leaf b(\d+)', sub)] == ids, 'leaves out of order in ' + fn
    assert sub.count('WT.node') == len(ids) - 1
assert nxt == 2 ** depth, 'blocks missing'
tdef = tree[tree.index('def tree'):tree.index('def W')]
assert [int(x) for x in re.findall(r'\bs(\d+)\b', tdef)] == list(range(len(files))), 'subtrees out of order'
assert tdef.count('WT.node') == len(files) - 1
print('%s: %d blocks of %d (+%d) letters in %d files spell the %d letters over %d symbols of %s' % (
    name, nxt, B, Kw, len(files), L, K, wordfile))
print('SHA-256 of the file%s: %s' % (' (decompressed)' if wordfile.endswith('.xz') else '', sha))
